parameters.jsCode:
// Generate actionable insights
const metrics = $input.item.json.metrics;
const sources = $input.item.json.topSources;

const insights = [];

// Response rate insight
if (metrics.response_rate < 5) {
  insights.push({
    type: 'warning',
    message: 'Response rate is below 5%. Consider revising your application strategy.',
    action: 'Review resume keywords and cover letter personalization'
  });
} else if (metrics.response_rate > 15) {
  insights.push({
    type: 'success',
    message: 'Excellent response rate! Your application strategy is working well.',
    action: 'Document what is working and scale successful approaches'
  });
}

// Application volume insight
if (metrics.applications_sent < 10) {
  insights.push({
    type: 'warning',
    message: 'Low application volume this week.',
    action: 'Consider increasing job discovery frequency or lowering AI score threshold'
  });
}

// Source performance insight
const bestSource = sources[0];
if (bestSource && bestSource.response_rate > 10) {
  insights.push({
    type: 'info',
    message: `${bestSource.source} is your best performing source with ${bestSource.response_rate}% response rate.`,
    action: `Focus more effort on ${bestSource.source} opportunities`
  });
}

// AI score insight
if (metrics.avg_ai_score < 7) {
  insights.push({
    type: 'info',
    message: 'Average AI score is below 7. You may be applying to less relevant positions.',
    action: 'Refine search queries to target more relevant roles'
  });
}

return {
  insights,
  recommendations: insights.map(i => i.action),
  timestamp: new Date().toISOString()
};

